 11	using vkernels::kernels::dsa_topk_transform_cpu;
 12	using vkernels::kernels::dsa_topk_transform_group_topk_supported;
 13	
 14	namespace {
 15	
 16	std::vector<int32_t> sorted_prefix(const std::vector<int32_t>& values, int32_t count) {
 17	  std::vector<int32_t> out(values.begin(), values.begin() + count);
 18	  std::sort(out.begin(), out.end());
 19	  return out;
 20	}
 21	
 22	std::vector<int32_t>
 23	expanded_group_tokens(int32_t group_begin, int32_t group_end, int32_t pool_size) {
 24	  std::vector<int32_t> out;
 25	  for (int32_t group = group_begin; group < group_end; ++group)
 26	    for (int32_t lane = 0; lane < pool_size; ++lane)
 27	      out.push_back(group * pool_size + lane);
 28	  std::sort(out.begin(), out.end());
 29	  return out;
 30	}
 31	
 32	} // namespace
