 34	TEST(DsaTopk, SupportedGroupTopkValues) {
 35	  EXPECT_TRUE(dsa_topk_transform_group_topk_supported(128));
 36	  EXPECT_TRUE(dsa_topk_transform_group_topk_supported(512));
 37	  EXPECT_FALSE(dsa_topk_transform_group_topk_supported(64));
 38	}
 39	
 40	TEST(DsaTopk, ReturnsContiguousHistoryWhenLengthDoesNotExceedK) {
 41	  std::vector<float> score(12);
 42	  for (int i = 0; i < 12; ++i)
 43	    score[i] = static_cast<float>(i);
 44	  std::vector<int32_t> lengths = {3};
 45	  std::vector<int32_t> out(256, -7);
 46	  dsa_topk_transform_cpu(1,
 47	                         score.data(),
 48	                         lengths.data(),
 49	                         out.data(),
 50	                         12,
 51	                         2,
 52	                         256,
 53	                         256,
 54	                         nullptr,
 55	                         0,
 56	                         nullptr,
 57	                         nullptr,
 58	                         nullptr,
 59	                         nullptr);
 60	  for (int32_t i = 0; i < 6; ++i)
 61	    EXPECT_EQ(out[i], i);
 62	  for (int32_t i = 6; i < 256; ++i)
 63	    EXPECT_EQ(out[i], -1);
 64	}
