  1	// meta/benchmarks/test_dsa_topk_correct.hip
  2	//
  3	// Device-vs-host correctness for the DSA pool-level radix top-k transform
  4	// (issue #56) on gfx942. The HIP kernel is compared against
  5	// vkernels::kernels::dsa_topk_transform_cpu across the decode guard
  6	// (length <= K), row_starts, page-table remap, ragged offsets, and seq tail.
  7	
  8	#include <hip/hip_runtime.h>
  9	
 10	#include <algorithm>
 11	#include <cstdint>
 12	#include <cstdio>
 13	#include <cstdlib>
 14	#include <vector>
 15	
 16	#include "vkernels/kernels/dsa_topk.hpp"
 17	
 18	#define CK(e, m)                                                       \
 19	  do {                                                                 \
 20	    hipError_t r = (e);                                                \
 21	    if (r != hipSuccess) {                                             \
 22	      std::fprintf(stderr, "%s: %s\n", m, hipGetErrorString(r));       \
 23	      std::exit(1);                                                    \
 24	    }                                                                  \
 25	  } while (0)
 26	
 27	namespace {
 28	
 29	bool compare_history(const std::vector<int32_t>& got,
 30	                     const std::vector<int32_t>& want, int32_t history_len) {
 31	  std::vector<int32_t> a(got.begin(), got.begin() + history_len);
 32	  std::vector<int32_t> b(want.begin(), want.begin() + history_len);
 33	  std::sort(a.begin(), a.end());
 34	  std::sort(b.begin(), b.end());
 35	  return a == b;
 36	}
 37	
 38	bool compare_tail(const std::vector<int32_t>& got, const std::vector<int32_t>& want,
 39	                  int32_t history_len, int32_t out_cols) {
 40	  for (int32_t i = history_len; i < out_cols; ++i)
 41	    if (got[i] != want[i]) return false;
 42	  return true;
 43	}
 44	
 45	struct Case {
 46	  const char* name;
 47	  int32_t batch_size;
 48	  int32_t score_stride;
 49	  int32_t pool_size;
 50	  int32_t token_topk;
 51	  int32_t out_cols;
 52	  std::vector<float> score;
 53	  std::vector<int32_t> lengths;
 54	  std::vector<int32_t> page_table;
 55	  int64_t page_table_stride;
 56	  std::vector<int32_t> page_table_row_index;
 57	  std::vector<int32_t> topk_indices_offset;
 58	  std::vector<int32_t> row_starts;
 59	  std::vector<int32_t> seq_lens;
 60	};
 61	
 62	bool run_case(const Case& c) {
 63	  std::vector<int32_t> want(static_cast<size_t>(c.batch_size) * c.out_cols, -1);
 64	  vkernels::kernels::dsa_topk_transform_cpu(
 65	      c.batch_size, c.score.data(), c.lengths.data(), want.data(),
 66	      c.score_stride, c.pool_size, c.token_topk, c.out_cols,
 67	      c.page_table.empty() ? nullptr : c.page_table.data(), c.page_table_stride,
 68	      c.page_table_row_index.empty() ? nullptr : c.page_table_row_index.data(),
 69	      c.topk_indices_offset.empty() ? nullptr : c.topk_indices_offset.data(),
 70	      c.row_starts.empty() ? nullptr : c.row_starts.data(),
 71	      c.seq_lens.empty() ? nullptr : c.seq_lens.data());
 72	
 73	  float* dscore = nullptr;
 74	  int32_t *dlengths = nullptr, *dout = nullptr, *dpage = nullptr;
 75	  int32_t *dpage_row = nullptr, *doffsets = nullptr, *drow_starts = nullptr, *dseq = nullptr;
 76	  CK(hipMalloc(&dscore, c.score.size() * sizeof(float)), "alloc score");
 77	  CK(hipMalloc(&dlengths, c.lengths.size() * sizeof(int32_t)), "alloc lengths");
 78	  CK(hipMalloc(&dout, want.size() * sizeof(int32_t)), "alloc out");
 79	  if (!c.page_table.empty()) CK(hipMalloc(&dpage, c.page_table.size() * sizeof(int32_t)), "alloc page");
 80	  if (!c.page_table_row_index.empty()) CK(hipMalloc(&dpage_row, c.page_table_row_index.size() * sizeof(int32_t)), "alloc page row");
