 36	bool run_case(int32_t pool_size, int32_t group_topk, bool paged, bool ragged, bool append_tail) {
 37	  constexpr int32_t batch = 3;
 38	  const int32_t token_topk = pool_size * group_topk;
 39	  const int32_t out_cols = token_topk + (append_tail ? pool_size - 1 : 0);
 40	  const std::vector<int32_t> lengths = {group_topk - 1, group_topk + 1, group_topk + 17};
 41	  const std::vector<int32_t> row_starts = {2, 1, 3};
 42	  const int64_t score_stride = row_starts[2] + lengths[2] + 5;
 43	  std::vector<float> score(static_cast<size_t>(batch) * score_stride, -1000.0f);
 44	  for (int32_t row = 0; row < batch; ++row) {
 45	    for (int32_t i = 0; i < lengths[row]; ++i) {
 46	      const uint32_t mixed = (static_cast<uint32_t>(i) * 104729u + row * 8191u) % 100000u;
 47	      score[static_cast<size_t>(row) * score_stride + row_starts[row] + i] =
 48	          static_cast<float>(mixed) / 100000.0f;
 49	    }
 50	  }
 51	
 52	  std::vector<int32_t> page_table;
 53	  std::vector<int32_t> page_rows = {2, 0, 1};
 54	  const int64_t page_stride = static_cast<int64_t>(lengths[2] + 1) * pool_size + pool_size;
 55	  if (paged) {
 56	    page_table.resize(static_cast<size_t>(batch) * page_stride);
 57	    for (int32_t row = 0; row < batch; ++row)
 58	      for (int64_t col = 0; col < page_stride; ++col)
 59	        page_table[static_cast<size_t>(row) * page_stride + col] =
 60	            row * 100000 + static_cast<int32_t>(col);
 61	  }
 62	  std::vector<int32_t> offsets = {17, 113, 911};
 63	  std::vector<int32_t> seq_lens = {lengths[0] * pool_size + 1,
 64	                                   lengths[1] * pool_size + pool_size - 1,
 65	                                   lengths[2] * pool_size + pool_size / 2};
 66	  std::vector<int32_t> reference(static_cast<size_t>(batch) * out_cols, -1);
 67	  vkernels::kernels::dsa_topk_transform_cpu(batch,
 68	                                            score.data(),
 69	                                            lengths.data(),
 70	                                            reference.data(),
 71	                                            score_stride,
 72	                                            pool_size,
 73	                                            token_topk,
 74	                                            out_cols,
 75	                                            paged ? page_table.data() : nullptr,
 76	                                            paged ? page_stride : 0,
 77	                                            paged ? page_rows.data() : nullptr,
 78	                                            ragged ? offsets.data() : nullptr,
 79	                                            row_starts.data(),
 80	                                            append_tail ? seq_lens.data() : nullptr);
 81	
 82	  float* d_score = device_copy(score);
 83	  int32_t* d_lengths = device_copy(lengths);
 84	  int32_t* d_out = nullptr;
 85	  CK(hipMalloc(&d_out, reference.size() * sizeof(int32_t)), "hipMalloc out");
 86	  int32_t* d_page = paged ? device_copy(page_table) : nullptr;
 87	  int32_t* d_page_rows = paged ? device_copy(page_rows) : nullptr;
 88	  int32_t* d_offsets = ragged ? device_copy(offsets) : nullptr;
 89	  int32_t* d_row_starts = device_copy(row_starts);
 90	  int32_t* d_seq_lens = append_tail ? device_copy(seq_lens) : nullptr;
 91	
 92	  vk_hip_dsa_topk_transform(batch,
 93	                            d_score,
 94	                            d_lengths,
 95	                            d_out,
 96	                            score_stride,
 97	                            pool_size,
 98	                            token_topk,
 99	                            out_cols,
100	                            d_page,
101	                            paged ? page_stride : 0,
102	                            d_page_rows,
103	                            d_offsets,
104	                            d_row_starts,
105	                            d_seq_lens);
106	  CK(hipGetLastError(), "vk_hip_dsa_topk_transform launch");
107	  CK(hipDeviceSynchronize(), "vk_hip_dsa_topk_transform sync");
108	  std::vector<int32_t> actual(reference.size());
109	  CK(hipMemcpy(actual.data(), d_out, actual.size() * sizeof(int32_t), hipMemcpyDeviceToHost),
110	     "hipMemcpy D2H");
111	
112	  device_free(d_score);
113	  device_free(d_lengths);
114	  device_free(d_out);
115	  device_free(d_page);
116	  device_free(d_page_rows);
117	  device_free(d_offsets);
118	  device_free(d_row_starts);
119	  device_free(d_seq_lens);
120	
121	  for (int32_t row = 0; row < batch; ++row) {
122	    auto ref_begin = reference.begin() + static_cast<size_t>(row) * out_cols;
123	    auto got_begin = actual.begin() + static_cast<size_t>(row) * out_cols;
124	    std::sort(ref_begin, ref_begin + out_cols);
125	    std::sort(got_begin, got_begin + out_cols);
126	    if (!std::equal(ref_begin, ref_begin + out_cols, got_begin)) {
127	      std::fprintf(stderr,
128	                   "mismatch pool=%d group_topk=%d row=%d paged=%d "
129	                   "ragged=%d tail=%d\n",
130	                   pool_size,
131	                   group_topk,
132	                   row,
133	                   paged,
134	                   ragged,
135	                   append_tail);
136	      return false;
137	    }
138	  }
139	  return true;
140	}
141	
142	} // namespace
