145	  struct Config {
146	    int32_t pool_size;
147	    int32_t group_topk;
148	  };
149	  const Config configs[] = {{16, 128}, {16, 160}, {16, 192}, {16, 224}, {8, 256}, {4, 512}};
150	  int failures = 0;
151	  for (const auto& config : configs) {
152	    for (int32_t mode = 0; mode < 3; ++mode) {
153	      for (bool append_tail : {false, true}) {
154	        const bool paged = mode == 1;
155	        const bool ragged = mode == 2;
156	        if (!run_case(config.pool_size, config.group_topk, paged, ragged, append_tail)) ++failures;
157	      }
158	    }
159	  }
160	  std::printf("%s (%d failure(s))\n", failures == 0 ? "PASS" : "FAIL", failures);
161	  return failures == 0 ? 0 : 1;
162	}

